CREATE EXTENSION IF NOT EXISTS vector WITH SCHEMA public;
CREATE SCHEMA IF NOT EXISTS insight;
CREATE SCHEMA IF NOT EXISTS insight_app;
CREATE OR REPLACE FUNCTION insight.allowed_user(uid integer) RETURNS boolean LANGUAGE sql STABLE AS $$
 SELECT current_setting('insight.tenant',true)='school-demo' AND
 (current_setting('insight.role',true)='Admin' OR uid::text=current_setting('insight.user_id',true))
$$;
CREATE OR REPLACE FUNCTION insight.allowed_section(sid integer) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,school AS $$
 SELECT current_setting('insight.tenant',true)='school-demo' AND
 (current_setting('insight.role',true)='Admin' OR
 (current_setting('insight.role',true)='Student' AND EXISTS(SELECT 1 FROM school.students s WHERE s.section_id=sid AND s.user_id::text=current_setting('insight.user_id',true))) OR
 (current_setting('insight.role',true)='Faculty' AND EXISTS(SELECT 1 FROM school.course_assignments ca JOIN school.faculty f USING(faculty_id) WHERE ca.section_id=sid AND f.user_id::text=current_setting('insight.user_id',true))))
$$;
CREATE OR REPLACE FUNCTION insight.allowed_subject(sid integer,subid integer) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,school AS $$
 SELECT current_setting('insight.tenant',true)='school-demo' AND
 (current_setting('insight.role',true)='Admin' OR
 (current_setting('insight.role',true)='Student' AND EXISTS(SELECT 1 FROM school.students s WHERE s.section_id=sid AND s.user_id::text=current_setting('insight.user_id',true))) OR
 (current_setting('insight.role',true)='Faculty' AND EXISTS(SELECT 1 FROM school.course_assignments ca JOIN school.faculty f USING(faculty_id) WHERE ca.section_id=sid AND ca.subject_id=subid AND f.user_id::text=current_setting('insight.user_id',true))))
$$;
CREATE VIEW insight.users WITH(security_barrier=true) AS SELECT u.user_id,u.username,u.first_name,u.last_name,r.role_name,u.is_active FROM school.users u JOIN school.roles r USING(role_id) WHERE insight.allowed_user(u.user_id);
CREATE VIEW insight.students WITH(security_barrier=true) AS SELECT s.student_id,s.user_id,s.admission_no,s.roll_no,s.section_id,u.first_name||' '||coalesce(u.last_name,'') AS student_name,c.class_name,sec.section_name FROM school.students s JOIN school.users u USING(user_id) JOIN school.sections sec USING(section_id) JOIN school.classes c USING(class_id) WHERE current_setting('insight.tenant',true)='school-demo' AND (current_setting('insight.role',true)='Admin' OR (current_setting('insight.role',true)='Student' AND insight.allowed_user(s.user_id)) OR (current_setting('insight.role',true)='Faculty' AND insight.allowed_section(s.section_id)));
CREATE VIEW insight.faculty WITH(security_barrier=true) AS SELECT f.faculty_id,f.user_id,u.first_name||' '||coalesce(u.last_name,'') AS faculty_name,f.designation FROM school.faculty f JOIN school.users u USING(user_id) WHERE insight.allowed_user(f.user_id);
CREATE VIEW insight.courses WITH(security_barrier=true) AS SELECT ca.assignment_id,ca.section_id,c.class_name,sec.section_name,sub.subject_name,sub.subject_id,f.faculty_id,u.first_name||' '||coalesce(u.last_name,'') AS faculty_name,cr.room_name,ca.periods_per_week FROM school.course_assignments ca JOIN school.sections sec USING(section_id) JOIN school.classes c USING(class_id) JOIN school.subjects sub USING(subject_id) JOIN school.faculty f USING(faculty_id) JOIN school.users u USING(user_id) JOIN school.classrooms cr USING(classroom_id) WHERE insight.allowed_subject(ca.section_id,ca.subject_id);
CREATE VIEW insight.attendance WITH(security_barrier=true) AS SELECT s.student_id,s.student_name,s.class_name,s.section_name,s.section_id,a.attendance_date,a.status,sub.subject_name,a.subject_id,p.period_no FROM school.student_attendance a JOIN insight.students s USING(student_id) JOIN school.subjects sub USING(subject_id) JOIN school.periods p USING(period_id) WHERE insight.allowed_subject(s.section_id,a.subject_id);
CREATE VIEW insight.v_student_attendance_report WITH(security_barrier=true) AS SELECT student_id,student_name,class_name,section_name,COUNT(*) AS total_periods,SUM(CASE WHEN status IN('Present','Late') THEN 1 ELSE 0 END) AS attended,ROUND(100.0*SUM(CASE WHEN status IN('Present','Late') THEN 1 ELSE 0 END)/COUNT(*),2) AS attendance_pct FROM insight.attendance GROUP BY student_id,student_name,class_name,section_name;
CREATE VIEW insight.v_exam_report WITH(security_barrier=true) AS SELECT s.student_id,s.student_name,s.class_name,s.section_name,e.exam_name,sub.subject_name,es.max_marks,es.pass_marks,m.marks_obtained,m.is_absent,CASE WHEN m.is_absent THEN 'Absent' WHEN m.marks_obtained IS NULL THEN 'Not entered' WHEN m.marks_obtained>=es.pass_marks THEN 'Pass' ELSE 'Fail' END AS result,g.grade FROM school.marks m JOIN insight.students s USING(student_id) JOIN school.exam_schedules es USING(exam_schedule_id) JOIN school.exams e USING(exam_id) JOIN school.subjects sub USING(subject_id) LEFT JOIN school.grade_scale g USING(grade_id) WHERE insight.allowed_subject(s.section_id,es.subject_id);
CREATE VIEW insight.v_pending_leaves WITH(security_barrier=true) AS SELECT lr.leave_id,u.first_name||' '||coalesce(u.last_name,'') AS applicant,r.role_name,lt.type_name,lr.from_date,lr.to_date,lr.status FROM school.leave_requests lr JOIN school.users u ON u.user_id=lr.applicant_id JOIN school.roles r USING(role_id) JOIN school.leave_types lt USING(leave_type_id) WHERE lr.status='Pending' AND insight.allowed_user(lr.applicant_id);
CREATE VIEW insight.v_timetable WITH(security_barrier=true) AS SELECT v.* FROM school.v_timetable v JOIN school.timetable t ON t.section_id=v.section_id AND t.day_of_week=v.day_of_week JOIN school.periods p ON p.period_id=t.period_id AND p.period_no=v.period_no WHERE insight.allowed_section(t.section_id) AND (current_setting('insight.role',true)!='Faculty' OR EXISTS(SELECT 1 FROM school.faculty f WHERE f.faculty_id=t.faculty_id AND f.user_id::text=current_setting('insight.user_id',true)));
CREATE VIEW insight.homework WITH(security_barrier=true) AS SELECT h.homework_id,h.title,h.description,h.section_id,c.class_name,sec.section_name,sub.subject_name,h.assigned_date,h.due_date FROM school.homework h JOIN school.sections sec USING(section_id) JOIN school.classes c USING(class_id) JOIN school.subjects sub USING(subject_id) WHERE insight.allowed_subject(h.section_id,h.subject_id);
CREATE VIEW insight.homework_submissions WITH(security_barrier=true) AS SELECT h.title,s.student_id,s.student_name,s.class_name,s.section_name,sub.subject_name,h.due_date,hs.status,hs.submitted_on FROM school.homework_submissions hs JOIN school.homework h USING(homework_id) JOIN insight.students s USING(student_id) JOIN school.subjects sub USING(subject_id) WHERE insight.allowed_subject(s.section_id,h.subject_id);
CREATE VIEW insight.assignments WITH(security_barrier=true) AS SELECT a.assignment_id,a.title,a.max_marks,a.due_date,c.class_name,sec.section_name,sub.subject_name FROM school.assignments a JOIN school.sections sec USING(section_id) JOIN school.classes c USING(class_id) JOIN school.subjects sub USING(subject_id) WHERE insight.allowed_subject(a.section_id,a.subject_id);
CREATE VIEW insight.assignment_submissions WITH(security_barrier=true) AS SELECT a.title,s.student_id,s.student_name,s.class_name,sub.subject_name,a.due_date,ss.status,ss.marks_obtained,a.max_marks FROM school.assignment_submissions ss JOIN school.assignments a USING(assignment_id) JOIN insight.students s USING(student_id) JOIN school.subjects sub USING(subject_id) WHERE insight.allowed_subject(s.section_id,a.subject_id);
CREATE VIEW insight.exams WITH(security_barrier=true) AS SELECT e.exam_name,c.class_name,sub.subject_name,es.exam_date,es.start_time,es.end_time,es.max_marks,es.pass_marks FROM school.exam_schedules es JOIN school.exams e USING(exam_id) JOIN school.classes c USING(class_id) JOIN school.subjects sub USING(subject_id) WHERE current_setting('insight.tenant',true)='school-demo' AND (current_setting('insight.role',true)='Admin' OR EXISTS(SELECT 1 FROM school.sections sec WHERE sec.class_id=e.class_id AND insight.allowed_subject(sec.section_id,es.subject_id)));
CREATE VIEW insight.progress_reports WITH(security_barrier=true) AS SELECT s.student_id,s.student_name,s.class_name,e.exam_name,pr.total_obtained,pr.total_max_marks,pr.percentage,pr.class_rank,g.grade,pr.is_published FROM school.progress_reports pr JOIN insight.students s USING(student_id) JOIN school.exams e USING(exam_id) LEFT JOIN school.grade_scale g USING(grade_id) WHERE (current_setting('insight.role',true)='Admin' OR (current_setting('insight.role',true)='Student' AND pr.is_published));
CREATE VIEW insight.grade_scale WITH(security_barrier=true) AS SELECT * FROM school.grade_scale WHERE current_setting('insight.tenant',true)='school-demo';
CREATE VIEW insight.faculty_attendance WITH(security_barrier=true) AS SELECT f.faculty_name,a.attendance_date,a.status,a.check_in,a.check_out FROM school.faculty_attendance a JOIN insight.faculty f USING(faculty_id);
CREATE VIEW insight.notifications WITH(security_barrier=true) AS SELECT notification_id,title,message,is_read,created_at FROM school.notifications WHERE insight.allowed_user(user_id);
CREATE TABLE insight_app.accounts(id bigserial PRIMARY KEY,tenant_id text NOT NULL,user_id int NOT NULL,username text NOT NULL,password_hash text NOT NULL,active boolean NOT NULL DEFAULT true,UNIQUE(tenant_id,username));
CREATE VIEW insight_app.identities AS SELECT a.id,a.tenant_id,a.username,a.password_hash,a.active AND u.is_active AS active,u.user_id,r.role_name,u.first_name||' '||coalesce(u.last_name,'') AS name,s.student_id,f.faculty_id FROM insight_app.accounts a JOIN school.users u USING(user_id) JOIN school.roles r USING(role_id) LEFT JOIN school.students s USING(user_id) LEFT JOIN school.faculty f USING(user_id);
CREATE TABLE insight_app.sessions(token_hash text PRIMARY KEY,account_id bigint REFERENCES insight_app.accounts(id),expires_at timestamptz NOT NULL);
CREATE TABLE insight_app.conversations(id uuid PRIMARY KEY,tenant_id text NOT NULL,account_id bigint REFERENCES insight_app.accounts(id),title text NOT NULL,provider text NOT NULL,model text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE insight_app.messages(id uuid PRIMARY KEY,conversation_id uuid REFERENCES insight_app.conversations(id) ON DELETE CASCADE,role text NOT NULL CHECK(role IN('user','assistant')),content text NOT NULL,payload jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE insight_app.queries(id uuid PRIMARY KEY,tenant_id text NOT NULL,account_id bigint REFERENCES insight_app.accounts(id),message_id uuid,question text NOT NULL,sql_text text NOT NULL,row_count int NOT NULL,duration_ms int NOT NULL,status text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE insight_app.feedback(id bigserial PRIMARY KEY,account_id bigint REFERENCES insight_app.accounts(id),message_id uuid NOT NULL REFERENCES insight_app.messages(id),rating int NOT NULL CHECK(rating IN(-1,1)),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(account_id,message_id));
CREATE TABLE insight_app.documents(id uuid PRIMARY KEY,tenant_id text NOT NULL,name text NOT NULL,sha256 text NOT NULL,status text NOT NULL DEFAULT 'pending',error text,pages int DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,sha256));
CREATE TABLE insight_app.chunks(id uuid PRIMARY KEY,document_id uuid NOT NULL REFERENCES insight_app.documents(id) ON DELETE CASCADE,tenant_id text NOT NULL,page int NOT NULL,section text NOT NULL,content text NOT NULL,embedding public.vector(384) NOT NULL,search tsvector GENERATED ALWAYS AS(to_tsvector('english',content)) STORED);
CREATE INDEX ON insight_app.chunks USING gin(search);
CREATE INDEX ON insight_app.messages(conversation_id,created_at);
CREATE TABLE insight_app.schema_catalog(id int PRIMARY KEY DEFAULT 1,source jsonb NOT NULL,updated_at timestamptz DEFAULT now());
REVOKE ALL ON SCHEMA public FROM PUBLIC;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA insight FROM PUBLIC;
